create table f_ref_option_margin_trs_relation(id string comment '主键ID',option_key_otc_trade_id string comment '期权合约ID',trs_key_otc_trade_id string comment '互换合约ID',status string comment '状态(Y-有效, N-无效)',created_by string comment '创建人',created_datetime string comment '创建时间',updated_by string comment '更新人',updated_datetime string comment '更新时间',data_time string comment '数据时间') partitioned by (busi_date string comment '数据日期') row format delimited fields terminated by ',' stored as orc;
